indirect enum Expr {
    case literal(Int)
    case binary(left: Expr, op: String, right: Expr)   // labeled children
}

func print(_ e: Expr) -> String {
    switch e {
    case .literal(let v):              return String(v)
    case .binary(let l, let o, let r): return "(\(print(l)) \(o) \(print(r)))"
    }
}
